-- Rollback-only fixture. Changing a sold job's service when a pricing template is involved
-- (sale.service_changed): template to template, template to a normal service and back, with the
-- stock put right each time; refused once materials are confirmed. Generated with the app's own code
-- (scripts/make-service-change-fixture.mjs; setup copied from pricing_templates.sql).
-- Isolated fixtures for the Costora-model pricing templates: all writes roll back.
-- Generated from tests/pricing-fixture.mjs with the app's own checkout and quotation code.
-- Templates inside events are written once and put back by pg_temp.tpl_restore.
begin;
create function pg_temp.tpl_t(n integer) returns jsonb language sql as $f$ select $json$[{"id":"a0000000-0000-4000-8000-000000000009","name":"Books","category":"Books","description":"Selectable paper, art-card cover and binding.","version":1,"archived":false,"variables":[{"key":"quantity","label":"Number of books","kind":"number","unit":"books","default":50,"min":1,"max":10000,"integer":true,"clientVisible":true},{"key":"sheets_per_book","label":"Sheets per book","kind":"number","unit":"sheets","default":25,"min":1,"max":500,"integer":true,"clientVisible":true},{"key":"inner_paper","label":"Inner paper","kind":"material","unit":"","default":1,"min":1,"max":2,"integer":true,"clientVisible":true,"options":[{"value":1,"label":"70 gsm paper","serviceId":"a0000000-0000-4000-8000-000000000005"},{"value":2,"label":"80 gsm paper","serviceId":"a0000000-0000-4000-8000-000000000006"}]},{"key":"cover_card","label":"Cover card","kind":"material","unit":"","default":1,"min":1,"max":1,"integer":true,"clientVisible":false,"options":[{"value":1,"label":"Art card","serviceId":"a0000000-0000-4000-8000-000000000007"}]}],"computed":[{"key":"paper_required","label":"Paper required","unit":"sheet","formula":"CEILING(quantity * sheets_per_book / 2 * 1.04)","expression":{"op":"CEILING","args":[{"op":"*","args":[{"op":"/","args":[{"op":"*","args":[{"op":"name","args":["quantity"]},{"op":"name","args":["sheets_per_book"]}]},{"op":"number","args":["2"]}]},{"op":"number","args":["1.04"]}]}]},"stock":{"variable":"inner_paper"}},{"key":"cards_required","label":"Cards required","unit":"card","formula":"CEILING(quantity * 1.05)","expression":{"op":"CEILING","args":[{"op":"*","args":[{"op":"name","args":["quantity"]},{"op":"number","args":["1.05"]}]}]},"stock":{"variable":"cover_card"}}],"expenses":[{"key":"paper_expense","label":"Paper","formula":"paper_required * (inner_paper_rate)","expression":{"op":"*","args":[{"op":"name","args":["paper_required"]},{"op":"name","args":["inner_paper_rate"]}]},"calculation":{"method":"orderInput","rate":"inner_paper_rate","input":"paper_required","capacity":"25"}},{"key":"card_expense","label":"Cards","formula":"cards_required * cover_card_rate","expression":{"op":"*","args":[{"op":"name","args":["cards_required"]},{"op":"name","args":["cover_card_rate"]}]}},{"key":"binding_expense","label":"Binding","formula":"quantity * (binding)","expression":{"op":"*","args":[{"op":"name","args":["quantity"]},{"op":"name","args":["binding"]}]},"calculation":{"method":"perItem","rate":"binding","input":"quantity","capacity":"25"}}],"pricing":{"method":"markup","rate":30,"floor":20,"maxDiscount":5,"rounding":100}},{"id":"a0000000-0000-4000-8000-000000000040","name":"Shirts","category":"","description":"","version":1,"archived":false,"variables":[{"key":"quantity","label":"Quantity","kind":"number","unit":"","default":50,"min":1,"max":100000,"integer":true,"clientVisible":true},{"key":"areas","label":"Print areas","kind":"options","unit":"","default":2,"min":1,"max":3,"integer":true,"clientVisible":true,"options":[{"value":1,"label":"Front"},{"value":2,"label":"Front and back"},{"value":3,"label":"Three areas"}]},{"key":"a4_ratio","label":"A4 ratio","kind":"number","unit":"","default":0.25,"min":0.01,"max":10,"integer":false,"clientVisible":false},{"key":"delivery","label":"Delivery","kind":"yesno","unit":"","default":1,"min":0,"max":1,"integer":true,"clientVisible":true}],"computed":[{"key":"prints","label":"Prints","unit":"prints","formula":"quantity * areas","expression":{"op":"*","args":[{"op":"name","args":["quantity"]},{"op":"name","args":["areas"]}]},"stock":null}],"expenses":[{"key":"garments","label":"Garments","formula":"quantity * shirt_cost","expression":{"op":"*","args":[{"op":"name","args":["quantity"]},{"op":"name","args":["shirt_cost"]}]}},{"key":"printing","label":"DTF","formula":"prints * a4_ratio * dtf_rate / 3 * 3","expression":{"op":"*","args":[{"op":"/","args":[{"op":"*","args":[{"op":"*","args":[{"op":"name","args":